Here is the commit message:
wifi: radiotap: reject radiotap with unknown bits

The radiotap parser is currently only used with the radiotap
namespace (not with vendor namespaces), but if the undefined
field 18 is used, the alignment/size is unknown as well. In
this case, iterator->_next_ns_data isn't initialized (it's
only set for skipping vendor namespaces), and syzbot points
out that we later compare against this uninitialized value.

Fix this by moving the rejection of unknown radiotap fields
down to after the in-namespace lookup, so it will really use
iterator->_next_ns_data only for vendor namespaces, even in
case undefined fields are present.

Cc: stable@vger.kernel.org
Fixes: 33e5a2f776e3 ("wireless: update radiotap parser")
Reported-by: syzbot+b09c1af8764c0097bb19@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/r/69944a91.a70a0220.2c38d7.00fc.GAE@google.com
Link: https://patch.msgid.link/20260217120526.162647-2-johannes@sipsolutions.net
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The radiotap parser in `ieee80211_radiotap_iterator_next()` incorrectly handles undefined fields that are within the defined bit range of the radiotap namespace. When `_arg_index < n_bits` but the field's alignment is zero (indicating an undefined field), the code falls through to the `if (!align)` block, which references `iterator->_next_ns_data`. This variable is only initialized when skipping vendor namespaces; for the radiotap namespace it remains uninitialized, leading to undefined behavior. The original early return for the radiotap namespace only applied when `_arg_index >= n_bits`, leaving this path unprotected. The fix moves the radiotap namespace check into the `if (!align)` block to ensure it triggers before the uninitialized value is used.

Here is the patch:

 int ieee80211_radiotap_iterator_next(
 	struct ieee80211_radiotap_iterator *iterator)
 {
 	while (1) {
 		int hit = 0;
 		int pad, align, size, subns;
 		uint32_t oui;

 		/* if no more EXT bits, that's it */
 		if ((iterator->_arg_index % 32) == IEEE80211_RADIOTAP_EXT &&
 		    !(iterator->_bitmap_shifter & 1))
 			return -ENOENT;

 		if (!(iterator->_bitmap_shifter & 1))
 			goto next_entry; /* arg not present */

 		/* get alignment/size of data */
 		switch (iterator->_arg_index % 32) {
 		case IEEE80211_RADIOTAP_RADIOTAP_NAMESPACE:
 		case IEEE80211_RADIOTAP_EXT:
 			align = 1;
 			size = 0;
 			break;
 		case IEEE80211_RADIOTAP_VENDOR_NAMESPACE:
 			align = 2;
 			size = 6;
 			break;
 		default:
 			if (!iterator->current_namespace ||
 			    iterator->_arg_index >= iterator->current_namespace->n_bits) {
-				if (iterator->current_namespace == &radiotap_ns)
-					return -ENOENT;
 				align = 0;
 			} else {
 				align = iterator->current_namespace->align_size[iterator->_arg_index].align;
 				size = iterator->current_namespace->align_size[iterator->_arg_index].size;
 			}
 			if (!align) {
+				if (iterator->current_namespace == &radiotap_ns)
+					return -ENOENT;
 				/* skip all subsequent data */
 				iterator->_arg = iterator->_next_ns_data;
 				/* give up on this namespace */
 				iterator->current_namespace = NULL;
 				goto next_entry;
 			}
 			break;
 		}

 		/*
 		 * arg is present, account for alignment padding
 		 *
 		 * Note that these alignments are relative to the start
 		 * of the radiotap header.  There is no guarantee
 		 * that the radiotap header itself is aligned on any
 		 * kind of boundary.
 		 *
 		 * The above is why get_unaligned() is used to dereference
 		 * multibyte elements from the radiotap area.
 		 */

 		pad = ((unsigned long)iterator->_arg -
 		       (unsigned long)iterator->_rtheader) & (align - 1);

 		if (pad)
 			iterator->_arg += align - pad;

 		if (iterator->_arg_index % 32 == IEEE80211_RADIOTAP_VENDOR_NAMESPACE) {
 			int vnslen;

 			if ((unsigned long)iterator->_arg + size -
 			    (unsigned long)iterator->_rtheader >
 			    (unsigned long)iterator->_max_length)
 				return -EINVAL;

 			oui = (*iterator->_arg << 16) |
 				(*(iterator->_arg + 1) << 8) |
 				*(iterator->_arg + 2);
 			subns = *(iterator->_arg + 3);

 			find_ns(iterator, oui, subns);

 			vnslen = get_unaligned_le16(iterator->_arg + 4);
 			iterator->_next_ns_data = iterator->_arg + size + vnslen;
 			if (!iterator->current_namespace)
 				size += vnslen;
 		}

 		/*
 		 * this is what we will return to user, but we need to
 		 * move on first so next call has something fresh to test
 		 */
 		iterator->this_arg_index = iterator->_arg_index;
 		iterator->this_arg = iterator->_arg;
 		iterator->this_arg_size = size;

 		/* internally move on the size of this arg */
 		iterator->_arg += size;

 		/*
 		 * check for insanity where we are given a bitmap that
 		 * claims to have more arg content than the length of the
 		 * radiotap section.  We will normally end up equalling this
 		 * max_length on the last arg, never exceeding it.
 		 */

 		if ((unsigned long)iterator->_arg -
 		    (unsigned long)iterator->_rtheader >
 		    (unsigned long)iterator->_max_length)
 			return -EINVAL;

 		/* these special ones are valid in each bitmap word */
 		switch (iterator->_arg_index % 32) {
 		case IEEE80211_RADIOTAP_VENDOR_NAMESPACE:
 			iterator->_reset_on_ext = 1;

 			iterator->is_radiotap_ns = 0;
 			/*
 			 * If parser didn't register this vendor
 			 * namespace with us, allow it to show it
 			 * as 'raw. Do do that, set argument index
 			 * to vendor namespace.
 			 */
 			iterator->this_arg_index =
 				IEEE80211_RADIOTAP_VENDOR_NAMESPACE;
 			if (!iterator->current_namespace)
 				hit = 1;
 			goto next_entry;
 		case IEEE80211_RADIOTAP_RADIOTAP_NAMESPACE:
 			iterator->_reset_on_ext = 1;
 			iterator->current_namespace = &radiotap_ns;
 			iterator->is_radiotap_ns = 1;
 			goto next_entry;
 		case IEEE80211_RADIOTAP_EXT:
 			/*
 			 * bit 31 was set, there is more
 			 * -- move to next u32 bitmap
 			 */
 			iterator->_bitmap_shifter =
 				get_unaligned_le32(iterator->_next_bitmap);
 			iterator->_next_bitmap++;
 			if (iterator->_reset_on_ext)
 				iterator->_arg_index = 0;
 			else
 				iterator->_arg_index++;
 			iterator->_reset_on_ext = 0;
 			break;
 		default:
 			/* we've got a hit! */
 			hit = 1;
  next_entry:
 			iterator->_bitmap_shifter >>= 1;
 			iterator->_arg_index++;
 		}

 		/* if we found a valid arg earlier, return it now */
 		if (hit)
 			return 0;
 	}
 }
 EXPORT_SYMBOL(ieee80211_radiotap_iterator_next);


